from maths_notes_v4.kit4 import H, I, Y, X, K, L, W, BK, Ex, mcq, grid, num

READ = {}
CARD = lambda title, cards, cols=None: dict({"kind": "sciCards", "title": title, "cards": cards}, **({"cols": cols} if cols else {}))

# =====================================================================================================
# 2.1 Physical quantities · 7TWSc.04
# =====================================================================================================
READ["2.1"] = L(
    H("Is it the same everywhere?",
      "A swimmer in Brazil and a swimmer in Japan both swim 50 m. One takes 23.4 s, the other 23.9 s. How can we be sure that both pools were really 50 m long, "
      "and that both clocks measured seconds the same way?",
      "Write down your idea. This lesson is about why everybody must measure with the **same units**."),
    I("Why do we measure?",
      "A **measurement** tells us **how much** of something there is. It always has two parts: a **number** and a **unit**.",
      fig=CARD("A number and a unit", [{"icon": "pill", "t": "10 ml", "d": "a dose of cough medicine"}, {"icon": "wheat", "t": "500 g", "d": "a bag of rice"},
                                       {"icon": "thermo", "t": "37.2 °C", "d": "a body temperature"}, {"icon": "clock", "t": "48.6 s", "d": "a 400 m race"}], 4),
      then=["'The medicine dose is 10' means nothing – 10 what? Without the unit, a measurement is useless and can even be dangerous.",
            "Scientists also measure to protect our world: the amount of dust in city air, the temperature of the sea, the number of turtles on a beach."]),
    I("Qualitative or quantitative?",
      "An observation can be described in two ways.",
      table=[["Kind of observation", "What it uses", "Example"],
             ["**qualitative**", "words only – how something looks, feels, smells or sounds", "the soup is very hot"],
             ["**quantitative**", "numbers and units, from a measuring instrument", "the soup is 82 °C"]],
      then=["Quantitative observations are **objective**: they are based on facts that anyone can check, not on opinions. "
            "'Very hot' to one person may be 'warm' to another, but 82 °C is 82 °C for everybody."]),
    Y("Words or numbers?",
      grid("s7u02r11", "Is each observation qualitative or quantitative?", ["Qualitative", "Quantitative"],
           [("The bread smells burnt.", "Qualitative"), ("The tree is 14 m tall.", "Quantitative"), ("The sky turned dark grey.", "Qualitative"),
            ("The cyclist travelled 18 km.", "Quantitative"), ("The sand feels rough.", "Qualitative")],
           "Is there a number with a unit?", "Smells, colours and textures are words (qualitative); 14 m and 18 km are numbers with units (quantitative).")),
    I("From body parts to standard units",
      "Long ago people measured with their bodies: a **hand** (the width of a hand), a **foot**, or a **cubit** (from the elbow to the tip of the longest finger).",
      fig={"kind": "sciFlow", "title": "How units became the same for everybody", "steps": [{"icon": "hands", "t": "Body parts", "d": "everyone's arm is different"},
                                                                                         {"icon": "ruler", "t": "Marked sticks and string", "d": "one town, one length"},
                                                                                         {"icon": "globe", "t": "An agreed metre", "d": "the same in every country"},
                                                                                         {"icon": "clock", "t": "Modern instruments", "d": "accurate and agreed"}]},
      then=["The problem: people's arms and feet are different sizes, so two traders could measure the same cloth and disagree. "
            "Countries slowly agreed on **standard units**. In the 1870s a metal bar that does not rust or bend was made to show the length of one metre exactly.",
            "Today we use instruments such as tape measures, electronic balances, stopwatches and thermometers, and the units are defined so precisely that every laboratory in the world agrees."]),
    I("SI units",
      "A **physical quantity** is anything in the physical world that can be measured. Scientists everywhere use the same set of units, called **SI units** (from the French Système International).",
      table=[["Physical quantity", "SI unit", "Symbol", "Other units you will meet"],
             ["length", "metre", "m", "km, cm, mm"], ["mass", "kilogram", "kg", "g, mg, tonne"], ["time", "second", "s", "minute, hour"],
             ["temperature", "kelvin", "K", "degree Celsius (°C)"], ["electric current", "ampere", "A", "milliampere (mA)"]],
      then=["In school science we often use smaller or more convenient units – centimetres, grams, °C – but we must always write the unit."]),
    Y("Which is an SI unit?",
      mcq("s7u02r12", "Which measurement is already written in an SI unit?",
          [("2.5 kg of potatoes", True, "Yes – the kilogram is the SI unit of mass."), ("750 g of flour", False, "Grams are fine to use, but the SI unit of mass is the kilogram."),
           ("21 °C in the classroom", False, "The SI unit of temperature is the kelvin."), ("3 minutes to boil an egg", False, "The SI unit of time is the second.")],
          "Look back at the SI table: metre, kilogram, second, kelvin, ampere.", "Only the kilogram is an SI unit here; g, °C and minutes are everyday units.")),
    X("The kilogram, not the gram",
      "Many students think the SI unit of mass is the gram because we use grams so often in the lab.",
      "The SI unit of mass is the **kilogram (kg)**. 1 kg = 1000 g. Grams are simply a smaller unit that is easier to use for small masses."),
    K("Key points",
      "A measurement is a **number + a unit**.",
      "**Qualitative** observations use words; **quantitative** observations use numbers and units and are **objective**.",
      "Body-part units such as the cubit were not reliable, so the world agreed on **standard units**.",
      "SI units: length – **metre (m)**, mass – **kilogram (kg)**, time – **second (s)**, temperature – **kelvin (K)**, current – **ampere (A)**."),
    book=BK(
        [("measurement", "a number and a unit that tell us how much of something there is"), ("qualitative", "described in words, without measurements"),
         ("quantitative", "described with numbers and units"), ("objective", "based on facts, not opinions"),
         ("physical quantity", "something that can be measured, such as length, mass or time"), ("SI unit", "a unit agreed by scientists all over the world")],
        [], [],
        [Ex("Write Ql (qualitative) or Qn (quantitative) for each observation.",
            ("The milk tastes sour.", "Ql"), ("The milk has been in the fridge for 6 days.", "Qn"), ("The lemon is bright yellow.", "Ql"), ("The lemon has a mass of 115 g.", "Qn")),
         Ex("Copy and complete the table of SI units.",
            ("length", "metre (m)"), ("mass", "kilogram (kg)"), ("time", "second (s)"), ("temperature", "kelvin (K)"), ("electric current", "ampere (A)")),
         Ex("A recipe says 'add 3 of sugar'. Explain why this instruction is not useful.", ans="It has no unit – 3 grams, 3 spoons and 3 kilograms are very different amounts."),
         Ex("Long ago, two traders measured the same rope in cubits and got different answers. Explain why, and how standard units solve the problem.",
            ans="A cubit depends on the length of each person's arm, so their cubits were different. A standard unit such as the metre is the same for everybody.", think=True),
         Ex("Lucas says 'the water is hot'. Rewrite his observation as a quantitative one and explain why scientists prefer it.",
            ans="For example: 'the water is 65 °C'. It is objective – anyone can check it with a thermometer – while 'hot' is an opinion.", think=True)],
        ["explain why every measurement needs a unit", "tell qualitative and quantitative observations apart", "explain why standard units are needed",
         "name the SI units of length, mass, time, temperature and current"],
        look=["qualitative and quantitative observations", "the table of SI units"],
        note="Read it after the video: qualitative and quantitative observations, standard units, SI units and the practice on paper (answers at the back)."),
)

