# 2.2 Measuring length · 7TWSc.02, 7TWSc.03, 7TWSc.04, 7TWSa.02
# =====================================================================================================
READ["2.2"] = L(
    H("How thick is one page?",
      "Pick up this page – or any page of a book. It is far too thin to measure with your ruler. Is it impossible to find its thickness?",
      "Think of a way to do it with an ordinary 30 cm rule before you read on."),
    I("Units of length",
      "The SI unit of length is the **metre (m)**. For very long or very short lengths we use bigger or smaller units.",
      table=[["Unit", "Symbol", "How big?", "Example"],
             ["kilometre", "km", "1 km = 1000 m", "the distance between two towns"], ["metre", "m", "1 m = 100 cm", "the height of a door is about 2 m"],
             ["centimetre", "cm", "1 cm = 10 mm", "the width of a fingernail is about 1 cm"], ["millimetre", "mm", "1 m = 1000 mm", "the thickness of a coin is about 2 mm"]],
      then=["To change a **big unit into a smaller unit, multiply**: 3.4 km = 3.4 × 1000 = 3400 m.",
            "To change a **small unit into a bigger unit, divide**: 85 mm = 85 ÷ 10 = 8.5 cm."]),
    Y("Convert it",
      num("s7u02r21", "A school running track is 0.4 km long. How many metres is that?", 400, "1 km = 1000 m, and you are changing to a smaller unit.",
          "Big unit → small unit: multiply. 0.4 × 1000 = 400 m.", errs=[(0.0004, "You divided – changing km to m means multiplying by 1000."), (40, "Multiply by 1000, not 100.")])),
    I("Choose the right instrument",
      "The instrument must match the length you are measuring.",
      table=[["Instrument", "Good for measuring …"],
             ["30 cm rule", "small objects: a pencil, a leaf, a book"], ["metre rule", "longer straight lengths: a table, a plank of wood"],
             ["soft (cloth) tape measure", "curved things: your waist, a tree trunk, a ball"], ["hard (steel) tape measure", "rooms, doors and furniture"],
             ["vernier calipers", "very small lengths: the width of a pin or a bolt, to 0.1 mm"],
             ["measuring wheel", "long distances on the ground: a sports field"], ["odometer", "the distance travelled by a car or bicycle"]]),
    I("Reading a rule correctly",
      "Line up one end of the object with the **zero mark**, not with the end of the rule (the end is often worn). Then read the scale at the other end.",
      fig={"kind": "sciParallax", "cm": 17, "obj": "crayon", "note": "Eye B, straight above the end, reads 17.0 cm"},
      then=["If your eye is to one side (A or C), the mark seems to move and you read a little too much or too little. This is a **parallax error**. "
            "Always look **straight down** at the mark."]),
    I("Predict, watch, explain: one sheet of paper",
      "A single sheet is too thin for a ruler, but a pile of sheets is not.",
      table=[["Step", "What we do"],
             ["1", "take **200** identical sheets from the same packet"], ["2", "squeeze them together and measure the pile: **19 mm**"],
             ["3", "divide by the number of sheets: 19 mm ÷ 200 = **0.095 mm**"]],
      then=["Measuring many sheets makes the length big enough to read. Dividing shares it equally between the sheets – and any small reading error is shared out too, "
            "so the answer for one sheet is more accurate. You can use the same trick for the thickness of a coin, a staple or a strand of thread."]),
    I("Repeat, check and average",
      "Before you trust a measurement, ask: **is it reasonable?** A pencil 85 cm long is not – measure again.",
      table=[["Key", "1st", "2nd", "3rd"], ["key P", "5.6 cm", "5.4 cm", "5.5 cm"], ["key Q", "6.2 cm", "6.0 cm", "8.9 cm"]],
      then=["Repeat each measurement at least three times. Results that are close together are **precise**.",
            "A result far from the others (8.9 cm) is an **outlier** – probably a mistake. Leave it out, then work out the **mean**: key Q = (6.2 + 6.0) ÷ 2 = 6.1 cm.",
            "If other people repeat your measurements and get the same results, your results are **reliable**."]),
    W("Working out a mean",
      "Four students measure the same desk: 61.5 cm, 61.8 cm, 70.2 cm and 61.7 cm. Find the best value for the length.",
      [("70.2 cm is far from the others", "it is an outlier, so leave it out"), ("61.5 + 61.8 + 61.7 = 185.0", "add the other three"), ("185.0 ÷ 3 = 61.7 (to 1 d.p.)", "divide by how many you added")],
      "about 61.7 cm", check="The mean lies between the smallest and largest results used (61.5 and 61.8)."),
    I("Accurate is not the same as precise",
      "**Accurate**: close to the **true value**. **Precise**: close **to each other** when repeated.",
      fig={"kind": "sciTargets"},
      then=["A ruler with a worn end might give 5.9, 5.9, 5.9 cm for a 6.0 cm key – precise, but not accurate."]),
    Y("Accurate or precise?",
      mcq("s7u02r22", "The true length of a nail is 4.0 cm. Sana measures it three times: 4.6 cm, 4.6 cm and 4.7 cm. Her results are …",
          [("precise, but not accurate", True, "Yes – they agree with each other but are far from 4.0 cm."), ("accurate and precise", False, "They are close together, but not close to 4.0 cm."),
           ("accurate, but not precise", False, "They are not close to the true value."), ("neither accurate nor precise", False, "They are close together, so they are precise.")],
          "Compare the results with each other, then with 4.0 cm.", "Close to each other = precise; far from the true value = not accurate.")),
    K("Key points",
      "1 km = 1000 m, 1 m = 100 cm, 1 cm = 10 mm. Big → small unit: **multiply**; small → big: **divide**.",
      "Choose the instrument to fit the length: rule, metre rule, tape measures, vernier calipers, measuring wheel.",
      "Start from the zero mark and look straight down to avoid a **parallax error**.",
      "Measure many thin things together and divide to find the thickness of one.",
      "Repeat, remove **outliers**, find the **mean**. **Accurate** = close to the true value; **precise** = close to each other."),
    book=BK(
        [("parallax error", "a wrong reading caused by looking at a scale from an angle"), ("outlier", "a result that is very different from the others"),
         ("mean", "the total of the results divided by the number of results"), ("precise", "repeated results that are close to each other"),
         ("accurate", "close to the true value"), ("reliable", "giving the same results when repeated, also by other people")],
        [], [],
        [Ex("Convert:", ("2.6 km into m", "2600 m"), ("450 cm into m", "4.5 m"), ("7.3 cm into mm", "73 mm"), ("1200 mm into m", "1.2 m")),
         Ex("Which instrument would you use to measure: (a) the length of a classroom (b) the distance round your head (c) the width of a pin?",
            ans="(a) a hard tape measure (b) a soft tape measure (c) vernier calipers"),
         Ex("A pile of 50 identical coins is 9.5 cm tall.", ("Find the thickness of one coin in cm.", "9.5 ÷ 50 = 0.19 cm"),
            ("Write your answer in mm.", "1.9 mm"), ("Why is this better than measuring one coin?", "the pile is big enough to read accurately, and the reading error is shared between 50 coins")),
         Ex("Three measurements of a book are 24.1 cm, 31.6 cm and 24.3 cm. Which is the outlier? Calculate the mean of the others.", ans="31.6 cm; (24.1 + 24.3) ÷ 2 = 24.2 cm"),
         Ex("Tom always reads his rule from slightly to the right. His three results are 12.4 cm, 12.4 cm and 12.5 cm; the true length is 12.0 cm. "
            "Are his results accurate, precise or both? What should he change?", ans="Precise but not accurate; he should look straight down at the mark to avoid parallax error.", think=True)],
        ["convert between km, m, cm and mm", "choose a suitable instrument to measure a length", "read a rule without a parallax error",
         "find the thickness of a thin object by measuring many", "spot outliers and calculate a mean", "explain accurate, precise and reliable"],
        look=["converting units of length", "how to avoid a parallax error", "outliers and the mean"],
        note="Read it after the video: units of length, instruments, parallax error, outliers and the mean, and the practice on paper (answers at the back)."),
)

