# 2.3 Area · 7TWSm.02
# =====================================================================================================
READ["2.3"] = L(
    H("Enough paint?",
      "A tin of paint covers 12 square metres. You want to paint a wall 5 m long and 3 m high. Is one tin enough?",
      "To answer, you need the **area** of the wall. Try it before you read on."),
    I("What is area?",
      "**Area** is the amount of flat surface something covers. We measure it by counting how many unit squares fit on it.",
      fig={"kind": "cells", "cells": [[i, j] for i in range(6) for j in range(4)], "grid": True},
      then=["Each small square here is 1 cm by 1 cm, so it has an area of **1 square centimetre (1 cm²)**. "
            "There are 6 squares in a row and 4 rows: 6 × 4 = **24 cm²**."]),
    I("Area of a rectangle",
      "Counting squares is slow. For a rectangle we can multiply instead:",
      table=[["Shape", "Formula", "Example"],
             ["rectangle", "**area = base × height**", "a phone screen 15 cm × 7 cm = 105 cm²"],
             ["square", "area = side × side", "a floor tile 30 cm × 30 cm = 900 cm²"]],
      then=["The unit of area is a **square unit**: mm², cm², m² or km². Both lengths must be in the **same unit** before you multiply."]),
    W("The wall from 'Start here'",
      "A wall is 5 m long and 3 m high. One tin of paint covers 12 m². Is one tin enough?",
      [("area = base × height", "the wall is a rectangle"), ("area = 5 × 3 = 15 m²", "multiply the two lengths, both in metres"), ("15 m² > 12 m²", "compare with what one tin covers")],
      "No – the wall is 15 m², so one tin (12 m²) is not enough; you need two tins.", check="5 × 3 = 15; 15 is bigger than 12."),
    I("Converting units of area",
      "1 m = 100 cm, so a 1 m square is 100 cm by 100 cm: **1 m² = 100 × 100 = 10 000 cm²**.",
      table=[["Length", "Area"], ["1 cm = 10 mm", "1 cm² = 10 × 10 = 100 mm²"], ["1 m = 100 cm", "1 m² = 100 × 100 = 10 000 cm²"], ["1 km = 1000 m", "1 km² = 1000 × 1000 = 1 000 000 m²"]],
      then=["To convert units of area, **square** the length factor – do not just multiply by 10 or 100."]),
    Y("Area of a tile",
      num("s7u02r31", "A rectangular tile is 9 cm long and 6 cm wide. What is its area in cm²?", 54, "Area of a rectangle = base × height.",
          "9 × 6 = 54 cm².", errs=[(15, "You added the sides – that is half the perimeter. Multiply them."), (30, "That is the perimeter. Area = base × height.")])),
    I("Predict, watch, explain: the area of a leaf",
      "A leaf is not a rectangle, so base × height does not work. Instead, draw round the leaf on **1 cm squared paper** and count.",
      fig={"kind": "sciLeafGrid"},
      then=["Count the squares **completely** covered. Then count the squares **more than half** covered – each counts as a whole square. Ignore squares less than half covered.",
            "Add the two counts to estimate the area in cm². The squares over half and under half roughly balance out. **Smaller squares** (for example 0.5 cm) give a more accurate estimate."]),
    Y("Count the squares",
      num("s7u02r32", "On 1 cm squared paper a leaf completely covers 27 squares and more than half covers 9 others. Squares less than half covered: 8. Estimate its area in cm².", 36,
          "Count full squares and more-than-half squares. Ignore the rest.", "27 + 9 = 36 cm² (the 8 small pieces are ignored).",
          errs=[(44, "Squares less than half covered are not counted."), (27, "Also count the squares more than half covered.")])),
    K("Key points",
      "**Area** is the amount of surface; units are cm², m², mm², km².",
      "Rectangle: **area = base × height** (both in the same unit).",
      "1 cm² = 100 mm²; 1 m² = 10 000 cm² – square the length factor.",
      "For irregular shapes, count squares on squared paper: full squares + squares more than half covered."),
    book=BK(
        [("area", "the amount of surface a shape covers"), ("square centimetre (cm²)", "the area of a square 1 cm by 1 cm"),
         ("square metre (m²)", "the area of a square 1 m by 1 m; 1 m² = 10 000 cm²"), ("irregular shape", "a shape with no simple formula for its area")],
        [], [],
        [Ex("Find the area of each rectangle.", ("12 cm by 4 cm", "48 cm²"), ("2.5 m by 4 m", "10 m²"), ("a square of side 8 mm", "64 mm²")),
         Ex("A classroom floor is 8 m long and 6 m wide. Floor tiles are sold in boxes that cover 2 m² each. How many boxes are needed?", ans="8 × 6 = 48 m²; 48 ÷ 2 = 24 boxes"),
         Ex("Convert: (a) 3 m² into cm² (b) 5 cm² into mm².", ans="(a) 30 000 cm² (b) 500 mm²"),
         Ex("A student says 1 m² = 100 cm² because 1 m = 100 cm. Explain the mistake.", ans="A 1 m square is 100 cm by 100 cm, so its area is 100 × 100 = 10 000 cm².", think=True),
         Ex("Two students estimate the area of the same leaf. Aiko uses 1 cm squares and gets 31 cm²; Ben uses 0.5 cm squares and gets 29.5 cm². Whose estimate is likely to be more accurate? Why?",
            ans="Ben's – smaller squares fit the curved edge more closely, so there is less error from the part-covered squares.", think=True)],
        ["explain what area means and give its units", "calculate the area of a rectangle", "convert between cm², mm² and m²", "estimate the area of an irregular shape by counting squares"],
        look=["area = base × height", "counting squares for a leaf"],
        note="Read it after the video: area of rectangles, units of area, the squared-paper method and the practice on paper (answers at the back)."),
)

